import { describe, expect, it } from 'vitest'
import {
  buildSourceControlAgentSaveTargets,
  getDefaultSourceControlAgentSaveTargetValue
} from './source-control-agent-action-dialog-support'

describe('source control agent action dialog save targets', () => {
  it('defaults saved launch recipes to the global target even when a repo target exists', () => {
    expect(buildSourceControlAgentSaveTargets('repo-1').map((target) => target.value)).toEqual([
      'none',
      'repo',
      'global'
    ])
    expect(getDefaultSourceControlAgentSaveTargetValue()).toBe('global')
  })
})

import { describe, expect, it } from 'vitest'
import {
  applyAgentPermissionMode,
  resolveAgentPermissionModeSummary,
  YOLO_TUI_AGENT_ARGS,
  YOLO_TUI_AGENT_ENV
} from './tui-agent-permissions'

describe('tui agent permissions', () => {
  it('recognizes the current default profile as yolo', () => {
    expect(
      resolveAgentPermissionModeSummary({
        agentDefaultArgs: YOLO_TUI_AGENT_ARGS,
        agentDefaultEnv: YOLO_TUI_AGENT_ENV
      })
    ).toBe('yolo')
  })

  it('recognizes an empty profile as manual', () => {
    expect(resolveAgentPermissionModeSummary({ agentDefaultArgs: {}, agentDefaultEnv: {} })).toBe(
      'manual'
    )
  })

  it('preserves custom agent arguments when applying manual mode', () => {
    const result = applyAgentPermissionMode({
      mode: 'manual',
      agentDefaultArgs: {
        claude: '--dangerously-skip-permissions',
        codex: '--model gpt-5'
      },
      agentDefaultEnv: YOLO_TUI_AGENT_ENV
    })

    expect(result.agentDefaultArgs.claude).toBe('')
    expect(result.agentDefaultArgs.codex).toBe('--model gpt-5')
    expect(result.agentDefaultEnv.goose).toEqual({})
  })

  it('reports mixed when custom arguments are present', () => {
    expect(
      resolveAgentPermissionModeSummary({
        agentDefaultArgs: {
          ...YOLO_TUI_AGENT_ARGS,
          codex: '--model gpt-5'
        },
        agentDefaultEnv: YOLO_TUI_AGENT_ENV
      })
    ).toBe('mixed')
  })
})

// Pins the contract between `runManagedHookInstallers` and the
// `agent_hook_install_failed` telemetry event: each catch must fire `track`
// with the correct agent label and a truncated error_message, and one
// installer's failure must not stop the others (fail-open semantics).

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

const { trackMock } = vi.hoisted(() => ({ trackMock: vi.fn() }))

vi.mock('../telemetry/client', () => ({ track: trackMock }))

import { runManagedHookInstallers } from './install-telemetry'

describe('runManagedHookInstallers', () => {
  beforeEach(() => {
    trackMock.mockReset()
    vi.spyOn(console, 'error').mockImplementation(() => {})
  })
  afterEach(() => {
    vi.restoreAllMocks()
  })

  it('runs every installer when none throw and never calls track', () => {
    const claude = vi.fn()
    const codex = vi.fn()
    runManagedHookInstallers([
      ['claude', claude],
      ['codex', codex]
    ])
    expect(claude).toHaveBeenCalledTimes(1)
    expect(codex).toHaveBeenCalledTimes(1)
    expect(trackMock).not.toHaveBeenCalled()
  })

  it('fires agent_hook_install_failed with the correct agent label when an installer throws', () => {
    runManagedHookInstallers([
      [
        'codex',
        () => {
          throw new Error('codex config malformed')
        }
      ]
    ])

    expect(trackMock).toHaveBeenCalledTimes(1)
    expect(trackMock).toHaveBeenCalledWith('agent_hook_install_failed', {
      agent: 'codex',
      error_message: 'codex config malformed'
    })
  })

  it('continues running later installers after an earlier one throws (fail-open)', () => {
    const codex = vi.fn()
    const gemini = vi.fn()
    runManagedHookInstallers([
      [
        'claude',
        () => {
          throw new Error('claude failed')
        }
      ],
      ['codex', codex],
      ['gemini', gemini]
    ])
    expect(codex).toHaveBeenCalledTimes(1)
    expect(gemini).toHaveBeenCalledTimes(1)
    expect(trackMock).toHaveBeenCalledTimes(1)
    expect(trackMock).toHaveBeenCalledWith(
      'agent_hook_install_failed',
      expect.objectContaining({ agent: 'claude' })
    )
  })

  it('truncates error_message to 200 chars', () => {
    const longMessage = 'x'.repeat(500)
    runManagedHookInstallers([
      [
        'gemini',
        () => {
          throw new Error(longMessage)
        }
      ]
    ])
    expect(trackMock).toHaveBeenCalledTimes(1)
    const [, props] = trackMock.mock.calls[0] as [string, { error_message: string }]
    expect(props.error_message.length).toBe(200)
  })

  it('handles non-Error throws', () => {
    runManagedHookInstallers([
      [
        'cursor',
        () => {
          throw 'cursor string failure'
        }
      ]
    ])
    expect(trackMock).toHaveBeenCalledWith('agent_hook_install_failed', {
      agent: 'cursor',
      error_message: 'cursor string failure'
    })
  })

  it('serializes thrown objects through JSON.stringify', () => {
    runManagedHookInstallers([
      [
        'cursor',
        () => {
          throw { code: 'EACCES', path: '/tmp' }
        }
      ]
    ])
    expect(trackMock).toHaveBeenCalledTimes(1)
    expect(trackMock).toHaveBeenCalledWith('agent_hook_install_failed', {
      agent: 'cursor',
      error_message: '{"code":"EACCES","path":"/tmp"}'
    })
  })

  it('does not throw when an installer throws undefined (regression for JSON.stringify undefined return)', () => {
    expect(() =>
      runManagedHookInstallers([
        [
          'cursor',
          () => {
            throw undefined
          }
        ]
      ])
    ).not.toThrow()
    expect(trackMock).toHaveBeenCalledTimes(1)
    const [eventName, props] = trackMock.mock.calls[0] as [string, { error_message: string }]
    expect(eventName).toBe('agent_hook_install_failed')
    expect(typeof props.error_message).toBe('string')
  })

  it('continues running later installers when track itself throws (telemetry must not break fail-open)', () => {
    const codex = vi.fn()
    trackMock.mockImplementationOnce(() => {
      throw new Error('telemetry blew up')
    })
    expect(() =>
      runManagedHookInstallers([
        [
          'claude',
          () => {
            throw new Error('claude failed')
          }
        ],
        ['codex', codex]
      ])
    ).not.toThrow()
    expect(codex).toHaveBeenCalledTimes(1)
  })
})

import { describe, expect, it, vi } from 'vitest'
import type { SFTPWrapper } from 'ssh2'

import {
  readHooksJsonRemote,
  writeHooksJsonRemote,
  writeManagedScriptRemote,
  writeTextFileRemoteAtomic
} from './installer-utils-remote'

type FakeFs = {
  files: Map<string, string>
  dirs: Set<string>
  modes: Map<string, number>
  openSshRenameCount: number
}

function createFakeSftp(
  opts: {
    plainRenameOverwrites?: boolean
    openSshRename?: boolean
    failDotFileWrites?: boolean
  } = {}
): {
  sftp: SFTPWrapper
  fs: FakeFs
} {
  const plainRenameOverwrites = opts.plainRenameOverwrites ?? true
  const fs: FakeFs = {
    files: new Map(),
    dirs: new Set(['/']),
    modes: new Map(),
    openSshRenameCount: 0
  }
  const noEntryError = (path: string): { code: number; message: string } => ({
    code: 2,
    message: `ENOENT ${path}`
  })
  const fakeStats = (mode: number): { mode: number } => ({ mode })

  const sftp = {
    readFile: (path: string, _enc: string, cb: (err: unknown, data?: string) => void): void => {
      const v = fs.files.get(path)
      if (v === undefined) {
        cb(noEntryError(path))
        return
      }
      cb(null, v)
    },
    writeFile: (
      path: string,
      content: string,
      options: string | { mode?: number },
      cb: (err: unknown) => void
    ): void => {
      if (opts.failDotFileWrites && path.includes('/.')) {
        cb({ code: 4, message: `write failed ${path}` })
        return
      }
      fs.files.set(path, content)
      if (typeof options !== 'string' && options.mode !== undefined) {
        fs.modes.set(path, options.mode)
      }
      cb(null)
    },
    rename: (src: string, dst: string, cb: (err: unknown) => void): void => {
      const v = fs.files.get(src)
      if (v === undefined) {
        cb(noEntryError(src))
        return
      }
      if (!plainRenameOverwrites && fs.files.has(dst)) {
        cb({ code: 4, message: `SSH_FX_FAILURE destination exists ${dst}` })
        return
      }
      fs.files.set(dst, v)
      fs.files.delete(src)
      const mode = fs.modes.get(src)
      if (mode !== undefined) {
        fs.modes.set(dst, mode)
        fs.modes.delete(src)
      }
      cb(null)
    },
    unlink: (path: string, cb: (err: unknown) => void): void => {
      if (!fs.files.has(path)) {
        cb(noEntryError(path))
        return
      }
      fs.files.delete(path)
      fs.modes.delete(path)
      cb(null)
    },
    chmod: (path: string, mode: number, cb: (err: unknown) => void): void => {
      fs.modes.set(path, mode)
      cb(null)
    },
    stat: (path: string, cb: (err: unknown, stats?: { mode: number }) => void): void => {
      if (!fs.files.has(path)) {
        cb(noEntryError(path))
        return
      }
      cb(null, fakeStats(fs.modes.get(path) ?? 0o100644))
    },
    readdir: (path: string, cb: (err: unknown, list?: { filename: string }[]) => void): void => {
      if (fs.dirs.has(path)) {
        cb(null, [])
        return
      }
      cb(noEntryError(path))
    },
    mkdir: (path: string, cb: (err: unknown) => void): void => {
      fs.dirs.add(path)
      cb(null)
    },
    ...(opts.openSshRename
      ? {
          ext_openssh_rename: (src: string, dst: string, cb: (err: unknown) => void): void => {
            fs.openSshRenameCount += 1
            const v = fs.files.get(src)
            if (v === undefined) {
              cb(noEntryError(src))
              return
            }
            fs.files.set(dst, v)
            fs.files.delete(src)
            const mode = fs.modes.get(src)
            if (mode !== undefined) {
              fs.modes.set(dst, mode)
              fs.modes.delete(src)
            }
            cb(null)
          }
        }
      : {})
  } as unknown as SFTPWrapper
  return { sftp, fs }
}

describe('installer-utils-remote', () => {
  it('returns {} when settings.json does not exist on the remote', async () => {
    const { sftp } = createFakeSftp()
    const result = await readHooksJsonRemote(sftp, '/home/u/.claude/settings.json')
    expect(result).toEqual({})
  })

  it('returns null when settings.json is malformed JSON', async () => {
    const { sftp, fs } = createFakeSftp()
    fs.files.set('/home/u/.claude/settings.json', 'not json {{')
    const result = await readHooksJsonRemote(sftp, '/home/u/.claude/settings.json')
    expect(result).toBeNull()
  })

  it('rethrows non-ENOENT read errors so callers can distinguish I/O failures from parse failures', async () => {
    const sftp = {
      readFile: (_path: string, _enc: string, cb: (err: unknown) => void): void => {
        // Why: SSH_FX_PERMISSION_DENIED (3) is a real I/O failure that should
        // not collapse into the same null result the parse-error path uses.
        cb({ code: 3, message: 'permission denied' })
      }
    } as unknown as SFTPWrapper
    await expect(readHooksJsonRemote(sftp, '/home/u/.claude/settings.json')).rejects.toMatchObject({
      code: 3
    })
  })

  it('times out remote reads that never call back', async () => {
    vi.useFakeTimers()
    try {
      const sftp = {
        readFile: vi.fn()
      } as unknown as SFTPWrapper
      const pending = readHooksJsonRemote(sftp, '/home/u/.claude/settings.json')
      let rejection: unknown = null
      pending.catch((error) => {
        rejection = error
      })

      await vi.advanceTimersByTimeAsync(30_000)

      expect(rejection).toBeInstanceOf(Error)
      await expect(pending).rejects.toThrow('Timed out waiting for SFTP readFile')
    } finally {
      vi.useRealTimers()
    }
  })

  it('atomically writes settings.json via tmp + rename', async () => {
    const { sftp, fs } = createFakeSftp()
    await writeHooksJsonRemote(sftp, '/home/u/.claude/settings.json', {
      hooks: { Stop: [{ hooks: [{ type: 'command', command: 'foo' }] }] }
    })
    expect(fs.files.has('/home/u/.claude/settings.json')).toBe(true)
    expect(fs.dirs.has('/home/u/.claude')).toBe(true)
    const contents = fs.files.get('/home/u/.claude/settings.json')!
    const parsed = JSON.parse(contents)
    expect(parsed.hooks.Stop[0].hooks[0].command).toBe('foo')
    // Tmp must be cleaned up.
    const tmp = Array.from(fs.files.keys()).find((k) => k.includes('.tmp'))
    expect(tmp).toBeUndefined()
    expect(fs.modes.get('/home/u/.claude/settings.json')).toBe(0o600)
  })

  it('preserves existing config file mode across atomic replacement', async () => {
    const { sftp, fs } = createFakeSftp()
    const path = '/home/u/.codex/config.toml'
    fs.files.set(path, 'old')
    fs.modes.set(path, 0o640)

    await writeTextFileRemoteAtomic(sftp, path, 'new')

    expect(fs.modes.get(path)).toBe(0o640)
  })

  it('uses OpenSSH overwrite rename when an atomic write updates an existing file', async () => {
    const { sftp, fs } = createFakeSftp({
      plainRenameOverwrites: false,
      openSshRename: true
    })
    const path = '/home/u/.claude/settings.json'
    fs.files.set(path, JSON.stringify({ hooks: {} }))

    await writeHooksJsonRemote(sftp, path, {
      hooks: { Stop: [{ hooks: [{ type: 'command', command: 'new' }] }] }
    })

    expect(fs.openSshRenameCount).toBe(1)
    expect(JSON.parse(fs.files.get(path)!).hooks.Stop[0].hooks[0].command).toBe('new')
  })

  it('leaves existing files intact when overwrite rename is unavailable', async () => {
    const { sftp, fs } = createFakeSftp({ plainRenameOverwrites: false })
    const path = '/home/u/.claude/settings.json'
    fs.files.set(path, JSON.stringify({ hooks: { Stop: [] } }))

    await expect(
      writeHooksJsonRemote(sftp, path, {
        hooks: { Stop: [{ hooks: [{ type: 'command', command: 'fallback' }] }] }
      })
    ).rejects.toMatchObject({ code: 4 })

    expect(JSON.parse(fs.files.get(path)!).hooks.Stop).toEqual([])
    expect(Array.from(fs.files.keys()).some((key) => key.includes('.tmp'))).toBe(false)
  })

  it('writes the managed script and chmods 0o755', async () => {
    const { sftp, fs } = createFakeSftp()
    await writeManagedScriptRemote(sftp, '/home/u/.orca/agent-hooks/claude-hook.sh', '#!/bin/sh\n')
    expect(fs.files.get('/home/u/.orca/agent-hooks/claude-hook.sh')).toBe('#!/bin/sh\n')
    expect(fs.modes.get('/home/u/.orca/agent-hooks/claude-hook.sh')).toBe(0o755)
  })

  it('replaces an existing managed script atomically via temp file rename', async () => {
    const { sftp, fs } = createFakeSftp({
      plainRenameOverwrites: false,
      openSshRename: true
    })
    const path = '/home/u/.orca/agent-hooks/claude-hook.sh'
    fs.files.set(path, 'old script')

    await writeManagedScriptRemote(sftp, path, 'new script')

    expect(fs.files.get(path)).toBe('new script')
    expect(fs.modes.get(path)).toBe(0o755)
    expect(Array.from(fs.files.keys()).some((key) => key.includes('.orca-backup-'))).toBe(false)
  })

  it('leaves the existing managed script intact when temp write fails', async () => {
    const { sftp, fs } = createFakeSftp({ failDotFileWrites: true })
    const path = '/home/u/.orca/agent-hooks/claude-hook.sh'
    fs.files.set(path, 'old script')

    await expect(writeManagedScriptRemote(sftp, path, 'new script')).rejects.toMatchObject({
      code: 4
    })
    expect(fs.files.get(path)).toBe('old script')
  })

  it('skips a no-op write when contents already match', async () => {
    const { sftp, fs } = createFakeSftp()
    const path = '/home/u/.claude/settings.json'
    await writeHooksJsonRemote(sftp, path, { hooks: {} })
    const beforeKey = fs.files.get(path)
    // Re-writing the same payload should produce the same content; there is
    // no rename/tmp cycle visible to a downstream observer beyond the
    // identical file body.
    await writeHooksJsonRemote(sftp, path, { hooks: {} })
    expect(fs.files.get(path)).toBe(beforeKey)
  })
})

import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  statSync,
  writeFileSync,
  chmodSync
} from 'fs'
import { homedir, tmpdir } from 'os'
import { join } from 'path'
import { spawnSync } from 'child_process'
import {
  buildWindowsAgentHookPostCommand,
  createManagedCommandMatcher,
  getSharedManagedScriptPath,
  hookDefinitionHasManagedCommand,
  removeManagedCommands,
  wrapPosixHookCommand,
  writeManagedScript,
  writeHooksJson,
  type HooksConfig
} from './installer-utils'

let tmpDir: string
let configPath: string

beforeEach(() => {
  tmpDir = mkdtempSync(join(tmpdir(), 'orca-installer-utils-test-'))
  configPath = join(tmpDir, 'settings.json')
})

afterEach(() => {
  rmSync(tmpDir, { recursive: true, force: true })
})

describe('writeHooksJson', () => {
  it('writes the config as formatted JSON', () => {
    const config: HooksConfig = {
      hooks: { Stop: [{ hooks: [{ type: 'command', command: 'foo' }] }] }
    }
    writeHooksJson(configPath, config)
    const written = JSON.parse(readFileSync(configPath, 'utf-8'))
    expect(written).toEqual(config)
  })

  it('creates the directory if it does not exist', () => {
    const nested = join(tmpDir, 'sub', 'dir', 'settings.json')
    writeHooksJson(nested, {})
    expect(existsSync(nested)).toBe(true)
  })

  it('creates a .bak file from the previous content before overwriting', () => {
    const original: HooksConfig = {
      hooks: { Stop: [{ hooks: [{ type: 'command', command: 'original' }] }] }
    }
    writeFileSync(configPath, `${JSON.stringify(original, null, 2)}\n`, 'utf-8')

    const updated: HooksConfig = {
      hooks: { Stop: [{ hooks: [{ type: 'command', command: 'updated' }] }] }
    }
    writeHooksJson(configPath, updated)

    const bak = JSON.parse(readFileSync(`${configPath}.bak`, 'utf-8'))
    expect(bak).toEqual(original)
  })

  it('does not create a .bak file when the config does not yet exist', () => {
    writeHooksJson(configPath, {})
    expect(existsSync(`${configPath}.bak`)).toBe(false)
  })

  it('is a no-op (does not rotate .bak) when the serialized content is unchanged', () => {
    const config: HooksConfig = {
      hooks: { Stop: [{ hooks: [{ type: 'command', command: 'foo' }] }] }
    }
    writeHooksJson(configPath, config)
    // First write had no prior file, so no .bak should exist.
    expect(existsSync(`${configPath}.bak`)).toBe(false)

    // Writing identical content must not create or rotate the .bak file.
    writeHooksJson(configPath, config)
    expect(existsSync(`${configPath}.bak`)).toBe(false)

    // A second distinct write must still produce a .bak from the prior content,
    // proving the no-op only triggers on byte-identical content.
    const updated: HooksConfig = {
      hooks: { Stop: [{ hooks: [{ type: 'command', command: 'bar' }] }] }
    }
    writeHooksJson(configPath, updated)
    const bak = JSON.parse(readFileSync(`${configPath}.bak`, 'utf-8'))
    expect(bak).toEqual(config)
  })

  it('updates the .bak file to the previous version on each write', () => {
    const v1: HooksConfig = { hooks: { Stop: [{ hooks: [{ type: 'command', command: 'v1' }] }] } }
    const v2: HooksConfig = { hooks: { Stop: [{ hooks: [{ type: 'command', command: 'v2' }] }] } }
    const v3: HooksConfig = { hooks: { Stop: [{ hooks: [{ type: 'command', command: 'v3' }] }] } }

    writeHooksJson(configPath, v1)
    writeHooksJson(configPath, v2)
    writeHooksJson(configPath, v3)

    // .bak should hold v2 (the version before v3)
    const bak = JSON.parse(readFileSync(`${configPath}.bak`, 'utf-8'))
    expect(bak).toEqual(v2)
    // configPath should hold v3
    const current = JSON.parse(readFileSync(configPath, 'utf-8'))
    expect(current).toEqual(v3)
  })

  it('leaves no temp file behind if the rename fails', () => {
    // Why: verifies the atomic cleanup — if the rename cannot complete (here,
    // because the target is a directory that cannot be overwritten), the finally
    // block must remove the temp file so ~/.claude is not littered with orphans.
    const blockingDir = configPath
    mkdirSync(blockingDir)

    expect(() => writeHooksJson(blockingDir, { hooks: {} })).toThrow()

    const entries = readdirSync(tmpDir)
    expect(entries.filter((e) => e.endsWith('.tmp'))).toHaveLength(0)
  })
})

describe('createManagedCommandMatcher', () => {
  const match = createManagedCommandMatcher('claude-hook.sh')

  it('matches commands containing the agent-hooks/<scriptFileName> path', () => {
    expect(
      match('/bin/sh "/Users/alice/Library/Application Support/Orca/agent-hooks/claude-hook.sh"')
    ).toBe(true)
    expect(match('/bin/sh "/some/other/location/agent-hooks/claude-hook.sh"')).toBe(true)
  })

  it('normalizes Windows backslashes so cmd-style paths still match', () => {
    expect(match('C:\\Users\\alice\\AppData\\Roaming\\Orca\\agent-hooks\\claude-hook.sh')).toBe(
      true
    )
  })

  it('returns false for unrelated commands', () => {
    expect(match(undefined)).toBe(false)
    expect(match('')).toBe(false)
    expect(match('echo "user-authored hook"')).toBe(false)
    // Same filename but not under an agent-hooks/ directory — treat as
    // user-authored to avoid stomping on someone else's hook.
    expect(match('/bin/sh "/home/alice/scripts/claude-hook.sh"')).toBe(false)
  })

  it('does not match hooks for a different agent', () => {
    expect(match('/bin/sh "/path/agent-hooks/gemini-hook.sh"')).toBe(false)
  })

  it('matches the guarded launcher form so wrapped commands sweep correctly', () => {
    // Why: wrapPosixHookCommand wraps the launcher in `if [ -x ... ]; then ...; fi`
    // so a stale entry no-ops instead of returning exit 127. The sweep on
    // install() must still recognize the guarded form as managed, otherwise
    // repeated installs would accumulate one guarded + one unguarded entry.
    expect(
      match(
        'if [ -x "/Users/alice/Library/Application Support/Orca/agent-hooks/claude-hook.sh" ]; then /bin/sh "/Users/alice/Library/Application Support/Orca/agent-hooks/claude-hook.sh"; fi'
      )
    ).toBe(true)
  })

  it('matches the legacy per-userData script path AND the new shared ~/.orca path', () => {
    // Why: install() must sweep old per-userData commands when migrating to
    // the shared ~/.orca script path, or stale launchers keep failing.
    expect(
      match("/bin/sh '/Users/alice/Library/Application Support/orca/agent-hooks/claude-hook.sh'")
    ).toBe(true)
    expect(match("/bin/sh '/Users/alice/.orca/agent-hooks/claude-hook.sh'")).toBe(true)
  })
})

describe('removeManagedCommands', () => {
  const match = createManagedCommandMatcher('copilot-hook.sh')

  it('removes managed direct bash/powershell/command fields', () => {
    const cleaned = removeManagedCommands(
      [
        {
          type: 'command',
          bash: '/bin/sh "/Users/alice/Orca/agent-hooks/copilot-hook.sh"',
          timeoutSec: 5
        },
        {
          type: 'command',
          powershell: "& 'C:\\Users\\alice\\Orca\\agent-hooks\\copilot-hook.sh'",
