  )
}

export function buildSourceControlAgentSaveTargets(repoId?: string | null): {
  value: string
  label: string
}[] {
  const targets = [
    {
      value: 'none',
      label: translate(
        'auto.components.right.sidebar.SourceControlAgentActionDialog.994cddd1f7',
        "Don't save"
      )
    }
  ]
  if (repoId) {
    targets.push({
